import { computed } from 'vue'

import colors from '@/lib/colors'
import preferences from '@/lib/preferences'
import stringHelpers from '@/lib/string'

import assetStore from '@/store/modules/assets'
import editStore from '@/store/modules/edits'
import episodeStore from '@/store/modules/episodes'
import sequenceStore from '@/store/modules/sequences'
import shotStore from '@/store/modules/shots'

export const entityListMixin = {
  emits: [
    'change-sort',
    'delete-all-tasks',
    'field-changed',
    'keep-task-panel-open',
    'scroll'
  ],

  provide() {
    return {
      activeFieldSort: computed(() => {
        const current = this.$store.getters[`${this.type}Sorting`]?.[0]
        return current && current.type === 'field' ? current : null
      })
    }
  },

  created() {
    this.initHiddenColumns(this.validationColumns, this.hiddenColumns)
  },

  mounted() {
    if (this.resizeHeaders) this.resizeHeaders()
    window.addEventListener('keydown', this.onKeyDown, false)
    window.addEventListener('keyup', this.onKeyUp, false)
    document.addEventListener('click', this.onHeaderMenuDocumentClick)
    document.addEventListener('keydown', this.onHeaderMenuDocumentKeyDown)
    this.stickedColumns =
      preferences.getObjectPreference(this.localStorageStickKey) || {}
    if (this.domEvents) this.addEvents(this.domEvents)
    if (typeof ResizeObserver !== 'undefined') {
      this.stickyHeaders = new Set()
      this.stickyHeadersObserver = new ResizeObserver(() =>
        this.updateOffsets()
      )
      this.observeStickyHeaders()
    }
  },

  // Sticky headers come and go with the stick menu and the display settings.
  updated() {
    this.observeStickyHeaders()
  },

  beforeUnmount() {
    this.stickyHeadersObserver?.disconnect()
    window.removeEventListener('keydown', this.onKeyDown)
    window.removeEventListener('keyup', this.onKeyUp)
    document.removeEventListener('click', this.onHeaderMenuDocumentClick)
    document.removeEventListener('keydown', this.onHeaderMenuDocumentKeyDown)
    if (this.domEvents) {
      this.removeEvents(this.domEvents)
      document.body.style.cursor = 'default'
    }
  },

  data() {
    return {
      columnSelectorDisplayed: false
    }
  },

  computed: {
    visibleMetadataDescriptors() {
      return this.metadataDescriptors.filter(descriptor => {
        const header = this.metadataDisplayHeaders[descriptor.field_name]
        return header === undefined || header
      })
    },

    nonStickedVisibleMetadataDescriptors() {
      return this.visibleMetadataDescriptors.filter(
        descriptor =>
          !this.stickedColumns[descriptor.id] &&
          this.metadataDescriptorIsInDepartmentFilter(descriptor)
      )
    },

    stickedVisibleMetadataDescriptors() {
      return this.visibleMetadataDescriptors.filter(
        descriptor =>
          this.stickedColumns[descriptor.id] &&
          this.metadataDescriptorIsInDepartmentFilter(descriptor)
      )
    },

    nonStickedDisplayedValidationColumns() {
      return this.displayedValidationColumns.filter(
        columnId =>
          !this.stickedColumns[columnId] &&
          this.validationColumnsIsInDepartmentFilter(columnId)
      )
    },

    stickedDisplayedValidationColumns() {
      return this.displayedValidationColumns.filter(
        columnId =>
          this.stickedColumns[columnId] &&
          this.validationColumnsIsInDepartmentFilter(columnId)
      )
    },

    // The sticky columns can change without any loading state: the task
    // types of the sequence and episode pages arrive once they have loaded.
    stickyColumnIds() {
      return [
        ...this.stickedVisibleMetadataDescriptors.map(({ id }) => id),
        ...this.stickedDisplayedValidationColumns
      ].join()
    },

    isEmptyTask() {
      return (
        !this.isEmptyList &&
        !this.isLoading &&
        this.validationColumns &&
        this.validationColumns.length === 0
      )
    }
  },

  methods: {
    // A sticky header resized by a drag or by its content moves the next
    // sticky columns.
    observeStickyHeaders() {
      if (!this.stickyHeadersObserver) return
      const headers = new Set(
        [
          this.$refs['th-name'],
          this.$refs['th-episode'],
          ...this.stickedVisibleMetadataDescriptors.map(
            (descriptor, j) => this.$refs[`editor-${j}`]?.[0]?.$el
          ),
          ...this.stickedDisplayedValidationColumns.map(
            (columnId, j) => this.$refs[`validation-${j}`]?.[0]?.$el
          )
        ].filter(Boolean)
      )
      this.stickyHeaders.forEach(header => {
        if (!headers.has(header)) this.stickyHeadersObserver.unobserve(header)
      })
      headers.forEach(header => {
        if (!this.stickyHeaders.has(header)) {
          this.stickyHeadersObserver.observe(header)
        }
      })
      this.stickyHeaders = headers
    },

    onBodyScroll(event) {
      const position = event.target
      this.$emit('scroll', position.scrollTop)
    },

    updateOffsets() {
      if (this.isLoading) {
        return
      }
      this.$nextTick(() => {
        let offset = this.$refs['th-name']
          ? this.$refs['th-name'].getBoundingClientRect().width
          : 0
        this.offsets = {}

        if (this.displaySettings.showInfos) {
          for (
            let metadataCol = 0;
            metadataCol < this.stickedVisibleMetadataDescriptors.length;
            metadataCol++
          ) {
            this.offsets[`editor-${metadataCol}`] = offset
            const editor = this.$refs[`editor-${metadataCol}`][0].$el
            offset += editor.getBoundingClientRect().width
          }
        }
        for (
          let validationCol = 0;
          validationCol < this.stickedDisplayedValidationColumns.length;
          validationCol++
        ) {
          this.offsets[`validation-${validationCol}`] = offset
          const validation = this.$refs[`validation-${validationCol}`][0].$el
          offset += validation.getBoundingClientRect().width
        }
      })
    },

    onInputKeyUp(event, i, j) {
      const listWidth = this.visibleMetadataDescriptors.length + 4
      const listHeight = this.displayedEpisodesLength
      this.keyMetadataNavigation(listWidth, listHeight, i, j, event.key)
      return this.pauseEvent(event)
    },

    getBackground(color) {
      return colors.hexToRGBa(color, 0.08)
    },

    buildHideKey(columnId) {
      return `column-${this.currentProduction.id}-${columnId}`
    },

    initHiddenColumns(validationColumns, hiddenColumns) {
      if (validationColumns && hiddenColumns) {
        validationColumns.forEach(columnId => {
          const key = this.buildHideKey(columnId)
          hiddenColumns[columnId] = localStorage.getItem(key) === 'true'
        })
      }
    },

    hideColumn(columnId) {
      const key = this.buildHideKey(columnId)
      let isColumnHidden = true
      if (localStorage.getItem(key) === 'true') {
        isColumnHidden = false
      }
      localStorage.setItem(key, isColumnHidden)
      this.hiddenColumns[columnId] = isColumnHidden
      return isColumnHidden
    },

    setScrollPosition(scrollPosition) {
      if (this.$refs.body) {
        this.$refs.body.scrollTop = scrollPosition
      }
    },

    setScrollLeftPosition(scrollPosition) {
      if (this.$refs.body) {
        this.$refs.body.scrollLeft = scrollPosition
      }
    },

    getValidationStyle(columnId) {
      const taskType = this.taskTypeMap.get(columnId)
      if (!taskType) return {}
      return {
        'border-left': `1px solid ${taskType.color}`,
        background: this.getBackground(taskType.color)
      }
    },

    onTaskSelected(validationInfo, sticked) {
      const columnOffset = this.stickedDisplayedValidationColumns.length
      const selection = []
      if (!sticked) {
        validationInfo = { ...validationInfo }
        validationInfo.y += columnOffset
      }
      this.$emit('keep-task-panel-open', true)
      if (validationInfo.isShiftKey) {
        if (this.lastSelection) {
          let startX = this.lastSelection.x
          let endX = validationInfo.x
          let startY = this.lastSelection.y
          if (!sticked) startY += columnOffset
          let endY = validationInfo.y
          const grid = this[`${this.type}SelectionGrid`]
          if (validationInfo.x < this.lastSelection.x) {
            startX = validationInfo.x
            endX = this.lastSelection.x
          }
          if (validationInfo.y < this.lastSelection.y) {
            startY = validationInfo.y
            endY = this.lastSelection.y
            if (!sticked) endY += columnOffset
          }

          for (let i = startX; i <= endX; i++) {
            for (let j = startY; j <= endY; j++) {
              const validationCell = this.$refs[`validation-${i}-${j}`]?.[0]
              const isSelectedCell = grid?.has(`${i}-${j}`)
              if (validationCell?.selectable && !isSelectedCell) {
                let y = validationCell.columnY
                if (!sticked) y += columnOffset

                selection.push({
                  entity: validationCell.entity,
                  column: validationCell.column,
                  task: validationCell.task,
                  x: validationCell.rowX,
                  y
                })
              }
            }
          }
          this.$store.commit('ADD_SELECTED_TASK', validationInfo)
        }
      } else if (!validationInfo.isCtrlKey) {
        this.$store.commit('CLEAR_SELECTED_TASKS')
      }
      if (selection.length === 0) {
        this.$store.commit('ADD_SELECTED_TASK', validationInfo)
      } else {
        this.$store.commit('ADD_SELECTED_TASKS', selection)
      }
      this.updateTaskInQuery()

      if (!validationInfo.isShiftKey && validationInfo.isUserClick) {
        const x = validationInfo.x
        let y = validationInfo.y
        if (!sticked) y -= columnOffset
        this.lastSelection = { x, y }
        const ref = `validation-${x}-${y}`
        const validationCell = this.$refs[ref][0]
        this.$nextTick(() => {
          this.scrollToValidationCell(validationCell)
        })
      }

      this.$nextTick(() => {
        this.$emit('keep-task-panel-open', false)
      })
    },

    onTaskUnselected(validationInfo, sticked) {
      if (!sticked) {
        validationInfo = { ...validationInfo }
        validationInfo.y += this.stickedDisplayedValidationColumns.length
      }
      if (!validationInfo.isCtrlKey) {
        if (this.nbSelectedTasks === 1) {
          this.$store.commit('REMOVE_SELECTED_TASK', validationInfo)
        } else {
          this.$store.commit('CLEAR_SELECTED_TASKS')
          this.$store.commit('ADD_SELECTED_TASK', validationInfo)
        }
      } else {
        this.$store.commit('REMOVE_SELECTED_TASK', validationInfo)
      }
      this.updateTaskInQuery()
    },

    hideHeaderMenu(refName) {
      this.$refs[refName]?.$el?.classList.add('hidden')
    },

    hideHeaderMenus(exceptRefName = null) {
      ;['headerMenu', 'headerMetadataMenu', 'headerFieldMenu']
        .filter(refName => refName !== exceptRefName)
        .forEach(refName => this.hideHeaderMenu(refName))
    },

    showHeaderMenuAt(
      refName,
      event,
      getHeaderElement,
      offset = {},
      isSameColumn = false
    ) {
      const headerMenuEl = this.$refs[refName]?.$el
      if (!headerMenuEl) return
      if (
        !event ||
        (!headerMenuEl.classList.contains('hidden') && isSameColumn)
      ) {
        headerMenuEl.classList.add('hidden')
        return
      }

      this.hideHeaderMenus(refName)
      headerMenuEl.classList.remove('hidden')

      const headerElement = getHeaderElement(event)
      const headerBox = headerElement.getBoundingClientRect()
      const left = headerBox.left + (offset.left || 0)
      const top = headerBox.bottom + (offset.top || 0)
      const width = Math.max(100, headerBox.width - 1)
      headerMenuEl.style.left = `${left}px`
      headerMenuEl.style.top = `${top}px`
      headerMenuEl.style.width = `${width}px`
    },

    showHeaderMenu(columnId, columnIndexInGrid, event) {
      this.showHeaderMenuAt(
        'headerMenu',
        event,
        event => event.target.closest('th'),
        { left: -3, top: 4 },
        this.lastHeaderMenuDisplayed === columnId
      )
      this.lastHeaderMenuDisplayed = columnId
      this.lastHeaderMenuDisplayedIndexInGrid = columnIndexInGrid
    },

    showFieldHeaderMenu(fieldName, label, event) {
      this.showHeaderMenuAt(
        'headerFieldMenu',
        event,
        event => event.target.closest('th'),
        { left: -3, top: 4 },
        this.lastFieldHeaderMenuDisplayed === fieldName
      )
      this.lastFieldHeaderMenuDisplayed = fieldName
      if (label !== undefined) this.lastFieldHeaderMenuLabel = label
    },

    onHeaderMenuDocumentClick(event) {
      if (
        event.target.closest('.header-menu') ||
        event.target.closest('.header-icon')
      ) {
        return
      }
      this.hideHeaderMenus()
    },

    onHeaderMenuDocumentKeyDown(event) {
      if (event.key === 'Escape') {
        this.hideHeaderMenus()
      }
    },

    onSortByFieldClicked() {
      const column = this.lastFieldHeaderMenuDisplayed
      const current = this.$store.getters[`${this.type}Sorting`]?.[0]
      const ascending =
        current && current.type === 'field' && current.column === column
          ? !current.ascending
          : true
      this.$emit('change-sort', {
        type: 'field',
        column,
        name: this.lastFieldHeaderMenuLabel,
        ascending
      })
      this.showFieldHeaderMenu(column)
    },

    onMinimizeColumnToggled() {
      this.hideColumn(this.lastHeaderMenuDisplayed)
      this.showHeaderMenu()
    },

    onDeleteAllTasksClicked() {
      this.$emit('delete-all-tasks', this.lastHeaderMenuDisplayed)
      this.showHeaderMenu()
    },

    onSortByTaskTypeClicked() {
      const taskTypeId = this.lastHeaderMenuDisplayed
      this.$emit('change-sort', {
        type: 'status',
        column: taskTypeId,
        name: this.taskTypeMap.get(taskTypeId)?.name || ''
      })
      this.showHeaderMenu()
    },

    onSelectColumn(type) {
      const taskTypeId = this.lastHeaderMenuDisplayed
      const selection = []

      let entities
      switch (type) {
        case 'asset':
          entities = assetStore.cache.result
          break
        case 'edit':
          entities = editStore.cache.result
          break
        case 'episode':
          entities = episodeStore.cache.result
          break
        case 'sequence':
          entities = sequenceStore.cache.result
          break
        case 'shot':
          entities = shotStore.cache.result
          break
        default:
          throw new Error(`Invalid entity type: ${type}`)
      }

      entities
        .filter(entity => !entity.canceled)
        .forEach((entity, i) => {
          selection.push({
            entity,
            column: this.taskTypeMap.get(taskTypeId),
            task: this.taskMap.get(entity.validations.get(taskTypeId)),
            x: i,
            y: this.lastHeaderMenuDisplayedIndexInGrid
          })
        })

      this.$store.commit('CLEAR_SELECTED_TASKS')
      this.$nextTick(() => {
        this.$store.commit('ADD_SELECTED_TASKS', selection)
        this.updateTaskInQuery()
        this.showHeaderMenu()
      })
    },

    // i = line number in entity group and k is the index of the entity group
    getEntityLineNumber(entities, i, k) {
      if (!this.$options.lineIndex || this.$options.lineIndexRef !== entities) {
        this.$options.lineIndex = {}
        this.$options.lineIndexRef = entities
      }
      const key = `${i}-${k}`
      const cached = this.$options.lineIndex[key]
      if (cached !== undefined) {
        return cached
      }
      let j = 0
      let index = 0
      while (j < k) {
        index += entities[j].length
        j++
      }
      const val = i + index
      this.$options.lineIndex[key] = val
      return val
    },

    getGroupKey(group, i, fieldName) {
      const key = group[0] ? group[0][fieldName] + group[0].canceled : ''
      return `${i}-${key}`
    },

    onDescriptionChanged(entry, value) {
      this.$emit('field-changed', {
        entry,
        fieldName: 'description',
        value
      })
    },

    onNumberFieldKeyDown(event) {
      if (['ArrowDown', 'ArrowUp'].includes(event.key)) {
        this.pauseEvent(event) // Requires dom mixin
      }
    },

    toggleColumnSelector() {
      this.columnSelectorDisplayed = !this.columnSelectorDisplayed
    },

    metadataDescriptorIsInDepartmentFilter(metadataDescriptor) {
      return (
        this.departmentFilter.length === 0 ||
        metadataDescriptor.departments.length === 0 ||
        this.departmentFilter.some(d =>
          metadataDescriptor.departments.includes(d)
        )
      )
    },

    validationColumnsIsInDepartmentFilter(columnId) {
      return (
        this.departmentFilter.length === 0 ||
        this.taskTypeMap.get(columnId)?.department_id === null ||
        this.departmentFilter.includes(
          this.taskTypeMap.get(columnId)?.department_id
        )
      )
    },

    isMetadataColumnEditAllowed(descriptorId) {
      if (typeof descriptorId !== 'string') return false
      if (this.isCurrentUserManager) return true
      if (!this.isCurrentUserSupervisor) return false

      const metadataDescriptor = this.visibleMetadataDescriptors.find(
        descriptor => descriptor.id === descriptorId
      )
      if (!metadataDescriptor) return false
      if (!this.user.departments.length) return true
      if (
        metadataDescriptor.departments.length !== this.user.departments.length
      ) {
        return false
      }
      return this.user.departments.every(department =>
        metadataDescriptor.departments.includes(department)
      )
    },

    isValidResolution(shot) {
      if (!shot) return true
      const res = this.getMetadataFieldValue({ field_name: 'resolution' }, shot)
      if (!res || res.length === 0) return true
      const isValid = new RegExp(/\d{3,4}x\d{3,4}/).test(res)
      return isValid
    },

    toggleStickedColumns(columnId) {
      const sticked = !this.stickedColumns[columnId]
      this.stickedColumns = {
        ...this.stickedColumns,
        [columnId]: sticked
      }
      preferences.setObjectPreference(
        this.localStorageStickKey,
        this.stickedColumns
      )
    },

    stickColumnClicked() {
      this.toggleStickedColumns(this.lastHeaderMenuDisplayed)
      this.showHeaderMenu()
    },

    metadataStickColumnClicked(event) {
      this.toggleStickedColumns(this.lastMetadataHeaderMenuDisplayed)
      this.showMetadataHeaderMenu(this.lastMetadataHeaderMenuDisplayed, event)
    },

    /*
     * Update the url query string with the currently selected task id.
     * (set a task_id field in the query string)
     * If 0 or more than 1 task is selected, remove the task_id field.
     */
    updateTaskInQuery() {
      if (this.nbSelectedTasks === 1) {
        const selectedTaskIds = Array.from(this.selectedTasks.keys())
        const taskId = selectedTaskIds[0]
        this.$router.push({
          query: {
            ...this.$route.query,
            task_id: taskId
          }
        })
      } else {
        this.$router.push({
          query: {
            ...this.$route.query,
            task_id: undefined
          }
        })
      }
    },

    /*
     * Get entity map for current entity type.
     *
     * Do not use computed property to avoid caching issues.
     */
    getEntityMap() {
      const entityMaps = {
        asset: assetStore.cache.assetMap,
        shot: shotStore.cache.shotMap,
        sequence: sequenceStore.cache.sequenceMap,
        episode: episodeStore.cache.episodeMap,
        edit: editStore.cache.editMap
      }
      return entityMaps[this.type]
    },

    /*
     * Select the task listed in the url query string (task_id field) if
     * present.
     */
    selectTaskFromQuery() {
      const taskId = this.$route.query.task_id
      const task = this.taskMap.get(taskId)
      if (task) {
        const entityMap = this.getEntityMap()
        const entity = entityMap.get(task.entity_id)

        if (entity) {
          const taskType = this.taskTypeMap.get(task.task_type_id)

          let list = this[`displayed${stringHelpers.capitalize(this.type)}s`]
          if (['asset', 'shot'].includes(this.type)) {
            list = list.flat()
          }
          const x = list.findIndex(e => e.id === entity.id)
          let y = this.stickedDisplayedValidationColumns.indexOf(
            task.task_type_id
          )
          if (y === -1) {
            const nonStickedIndex =
              this.nonStickedDisplayedValidationColumns.indexOf(
                task.task_type_id
              )
            if (nonStickedIndex > -1) {
              y =
                nonStickedIndex + this.stickedDisplayedValidationColumns.length
            }
          }
          if (y > -1) {
            this.$store.commit('ADD_SELECTED_TASK', {
              task,
              entity,
              column: taskType,
              x,
              y
            })
          }
        }
      }
    },

    startBrowsing(event) {
      if (event.target.tagName === 'INPUT') return

      document.body.style.cursor = 'grabbing'
      this.isBrowsingX = true
      this.isBrowsingY = true
      this.initialClientX = this.getClientX(event)
      this.initialClientY = this.getClientY(event)
    },

    startBrowsingX(event) {
      document.body.style.cursor = 'grabbing'
      this.isBrowsingX = true
      this.initialClientX = this.getClientX(event)
    },

    startBrowsingY(event) {
      document.body.style.cursor = 'grabbing'
      this.isBrowsingY = true
      this.initialClientY = this.getClientY(event)
    },

    stopBrowsing(event) {
      document.body.style.cursor = 'default'
      this.isBrowsingX = false
      this.isBrowsingY = false
      this.initialClientX = null
      this.initialClientY = null
    },

    onMouseMove(event) {
      if (this.isBrowsingX) this.scrollTableLeft(event)
      if (this.isBrowsingY) this.scrollTableTop(event)
    },

    scrollTableLeft(event) {
      const tableWrapper = this.$refs.body
      const previousLeft = tableWrapper.scrollLeft
      const movementX =
        event.movementX || this.getClientX(event) - this.initialClientX
      const newLeft = previousLeft - movementX
      this.initialClientX = this.getClientX(event)
      tableWrapper.scrollLeft = newLeft
    },

    scrollTableTop(event) {
      const tableWrapper = this.$refs.body
      const previousTop = tableWrapper.scrollTop
      const movementY =
        event.movementY || this.getClientY(event) - this.initialClientY
      const newTop = previousTop - movementY
      this.initialClientY = this.getClientY(event)
      tableWrapper.scrollTop = newTop
    }
  },

  watch: {
    nbSelectedTasks() {
      this.updateTaskInQuery()
    },

    stickyColumnIds() {
      this.updateOffsets()
    },

    'displaySettings.bigThumbnails'() {
      this.updateOffsets()
    },

    // The infos add or remove sticky columns (metadata, TV show episodes).
    'displaySettings.showInfos'() {
      this.updateOffsets()
    }
  }
}
